(()=>{const form=document.querySelector('#catalog-filters');if(!form)return;form.onsubmit=e=>e.preventDefault();const update=()=>{let count=0;for(const card of document.querySelectorAll('.catalog-item')){const yes=(document.querySelector('#catalog-case').value==='all'||card.dataset.case===document.querySelector('#catalog-case').value)&&(document.querySelector('#catalog-format').value==='all'||card.dataset.formats.split(' ').includes(document.querySelector('#catalog-format').value))&&card.textContent.toLocaleLowerCase().includes(document.querySelector('#catalog-search').value.toLocaleLowerCase());card.hidden=!yes;if(yes)count++}document.querySelector('#catalog-count').textContent=count+(document.documentElement.lang==='de'?' Materialien':' resources')};form.addEventListener('input',update);form.addEventListener('change',update);update()})();
